 public static class GlassProgram {
  public static void Run(string[] args) {
   if(args.Length>1&&args[0]=="--preview") {var app=new Application();var w=new GlassPlanner(null,true);if(args.Contains("--light"))w.SetEnvironment(true);w.Preview(args[1]);return;}
   bool first;using(var mutex=new Mutex(true,"Local\\PersonalPlanDeskPlanner",out first)) {
    if(!first){MessageBox.Show("Personal Plan 已在运行，请双击托盘图标。","Personal Plan");return;}
    try {var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};app.DispatcherUnhandledException+=delegate(object s,DispatcherUnhandledExceptionEventArgs e){e.Handled=true;MessageBox.Show(e.Exception.Message,"操作未完成");};
     using(var signal=new EventWaitHandle(false,EventResetMode.AutoReset,"Local\\PersonalPlanExit")) {
      var window=new GlassPlanner(new Storage(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"Data")),false);
      var wait=ThreadPool.RegisterWaitForSingleObject(signal,delegate{app.Dispatcher.BeginInvoke((Action)window.Quit);},null,Timeout.Infinite,false);
      try{app.Run(window);}finally{wait.Unregister(null);}
     }
    } catch(Exception e){MessageBox.Show(e.Message,"Personal Plan");}finally{mutex.ReleaseMutex();}
   }
  }
 }
