  static SolidColorBrush Brush(string color){return (SolidColorBrush)new BrushConverter().ConvertFromString(color);}
  static ImageSource LoadAppIcon(){using(var stream=System.Reflection.Assembly.GetExecutingAssembly().GetManifestResourceStream("DeskPlanner.AppIcon.png")){if(stream==null)return null;var image=new BitmapImage();image.BeginInit();image.CacheOption=BitmapCacheOption.OnLoad;image.StreamSource=stream;image.EndInit();image.Freeze();return image;}}
  bool Light {get{return state.Settings.EnvironmentMode=="light";}}
  string MapColor(string c){if(!Light)return c;switch(c.ToUpperInvariant()){case "#E8F4FF":return state.Settings.TextColor;case "#D9F9FF":return "#123E56";case "#8FEAF3":case "#75ECF9":case "#67E8F9":case "#74E8F7":return "#006B84";case "#BCD3E2":case "#C2DAE7":case "#C4D6E4":case "#D6EAF3":return "#34566C";case "#91BBCB":case "#9ABACD":return "#44677D";default:return c;}}
  public void SetEnvironment(bool light){if(Light){state.Settings.LightBackgroundColor=state.Settings.BackgroundColor;state.Settings.LightTextColor=state.Settings.TextColor;}else{state.Settings.DarkBackgroundColor=state.Settings.BackgroundColor;state.Settings.DarkTextColor=state.Settings.TextColor;}state.Settings.EnvironmentMode=light?"light":"dark";state.Settings.BackgroundColor=light?state.Settings.LightBackgroundColor:state.Settings.DarkBackgroundColor;state.Settings.TextColor=light?state.Settings.LightTextColor:state.Settings.DarkTextColor;}
  string ThemeStyles(){if(!Light)return Styles;return Styles.Replace("#E8F4FF",state.Settings.TextColor).Replace("#000814","#FFFFFF").Replace("Opacity='0.9'","Opacity='0.28'").Replace("#67E8F9","#006B84").Replace("#5078DAE8","#40007896").Replace("#080A2135","#08FFFFFF").Replace("#364C7D96","#55395F75").Replace("#74E8F7","#006B84").Replace("#12102C40","#18FFFFFF").Replace("#1841C9DC","#16007896").Replace("#264AC8DB","#44007896").Replace("#8AB8CEDD","#8A395F75").Replace("#08081D2B","#08FFFFFF").Replace("#75ECF9","#006B84").Replace("#164ACCDD","#16007896").Replace("#104ACCDD","#10007896");}
  TextBlock Label(string text,double size,string color){return new TextBlock{Text=text,Tag=color,FontSize=size,Foreground=Brush(MapColor(color)),VerticalAlignment=VerticalAlignment.Center,TextTrimming=TextTrimming.CharacterEllipsis};}
  Button Btn(string title,Action action){var b=new Button{Content=title};b.Click+=delegate{action();};return b;}
  Grid Columns(params double[] widths){var g=new Grid();foreach(double n in widths)g.ColumnDefinitions.Add(new ColumnDefinition{Width=n==1?new GridLength(1,GridUnitType.Star):new GridLength(n)});return g;}
  void Place(Grid g,UIElement c,int column){Grid.SetColumn(c,column);g.Children.Add(c);}
  void Add(Grid g,UIElement c,int row){Grid.SetRow(c,row);g.Children.Add(c);}
  void ApplyLabels(DependencyObject parent){foreach(object child in LogicalTreeHelper.GetChildren(parent)){var node=child as DependencyObject;if(node==null)continue;var text=node as TextBlock;if(text!=null&&text.Tag is string)text.Foreground=Brush(MapColor((string)text.Tag));ApplyLabels(node);}}
  void ApplyTheme(){Resources=(ResourceDictionary)XamlReader.Parse(ThemeStyles());Color color=(Color)ColorConverter.ConvertFromString(state.Settings.BackgroundColor);color.A=(byte)Math.Round(Math.Max(0,Math.Min(100,state.Settings.BackgroundAlpha))*2.55);glass.Background=new SolidColorBrush(color);glass.BorderBrush=Brush(Light?"#40395F75":"#304FA9BD");Topmost=state.Settings.Topmost;Foreground=Brush(state.Settings.TextColor);entry.Foreground=notes.Foreground=summary.Foreground=Foreground;entry.CaretBrush=notes.CaretBrush=Brush(MapColor("#8FEAF3"));foreach(var editor in new[]{entry,notes,summary})editor.Effect=new DropShadowEffect{Color=Light?Colors.White:Colors.Black,BlurRadius=Light?1:2,ShadowDepth=Light?0:1,Opacity=Light?0.35:0.8};ApplyLabels(root);progress.Background=Brush(MapColor("#8FEAF3"));aiButton.Foreground=Brush(MapColor("#8FEAF3"));modeButton.Content=Light?"浅环境":"深环境";modeButton.Foreground=Brush(MapColor("#8FEAF3"));if(mini!=null){mini.Resources=Resources;var b=(Border)mini.Content;b.Background=glass.Background;b.BorderBrush=glass.BorderBrush;ApplyLabels(b);}}
  void Save(){if(preview)return;try{store.Save(state);status.Text="已保存  ·  17:30 提醒";}catch(Exception e){status.Text="保存失败";MessageBox.Show(e.Message,"数据保存失败");}}
  Note Note(string k,DateTime d){string p=Logic.Key(k,d);var n=state.Notes.FirstOrDefault(x=>x.Kind==k&&x.Period==p);if(n==null){n=new Note{Kind=k,Period=p};state.Notes.Add(n);}return n;}
  void Flush(){if(rendering||notes==null)return;saveTimer.Stop();Note(kind,date).Text=notes.Text;Save();}
  void Render(){rendering=true;dateButton.Content=date.ToString("yyyy / MM / dd");period.Text=Logic.Iso(Logic.Start(kind,date))+(kind=="day"?"  "+date.ToString("ddd"):" — "+Logic.Iso(Logic.End(kind,date)));page.Text=kind=="day"?"D "+date.DayOfYear.ToString("000")+"/"+(DateTime.IsLeapYear(date.Year)?366:365):kind=="week"?"W "+System.Globalization.CultureInfo.InvariantCulture.Calendar.GetWeekOfYear(date,System.Globalization.CalendarWeekRule.FirstFourDayWeek,DayOfWeek.Monday).ToString("00"):"M "+date.Month.ToString("00")+"/12";
   foreach(var t in tabs){t.Value.Background=t.Key==kind?Brush(Light?"#16007896":"#1847C7DD"):Brushes.Transparent;t.Value.Foreground=t.Key==kind?Brush(MapColor("#8FEAF3")):Brush(state.Settings.TextColor);t.Value.BorderBrush=Brush(Light?"#55006B84":"#264AC8DB");t.Value.BorderThickness=t.Key==kind?new Thickness(0,0,0,1):new Thickness(0);}
   tasks.Items.Clear();foreach(var i in Current()){var check=new CheckBox{Tag=i,IsChecked=i.Done};var text=Label(i.Text,13,state.Settings.TextColor);text.TextWrapping=TextWrapping.Wrap;if(i.Done)text.TextDecorations=TextDecorations.Strikethrough;check.Content=text;check.Checked+=TaskChecked;check.Unchecked+=TaskChecked;var row=new ListBoxItem{Content=check,Tag=i};row.MouseRightButtonUp+=delegate{row.IsSelected=true;};var menu=new ContextMenu();menu.Items.Add(Menu("编辑",Edit));menu.Items.Add(Menu("删除",Delete));menu.Items.Add(Menu("移到下期",Carry));row.ContextMenu=menu;tasks.Items.Add(row);}
   empty.Visibility=tasks.Items.Count==0?Visibility.Visible:Visibility.Collapsed;var n=Note(kind,date);notes.Text=n.Text;summary.Text=String.IsNullOrEmpty(n.AI)?"总结将根据你的任务与复盘备注生成。":n.AI+"\n\n生成于 "+n.GeneratedAt;rendering=false;UpdateStats();}
  MenuItem Menu(string title,Action action){var i=new MenuItem{Header=title};i.Click+=delegate{action();};return i;}
  System.Collections.Generic.List<Item> Current(){return state.Items.Where(x=>x.Kind==kind&&x.Period==Logic.Key(kind,date)).ToList();}
  void UpdateStats(){if(tasks==null)return;var a=Current();stats.Text=Logic.Name(kind)+"计划 "+Logic.Rate(a)+(kind=="day"?"":"   |   日任务 "+Logic.Rate(state.Items.Where(x=>x.Kind=="day"&&Logic.InPeriod(x,kind,date))));progress.Width=Math.Max(0,root.ActualWidth)*(a.Count==0?0:(double)a.Count(x=>x.Done)/a.Count);UpdateMini();}
  void TaskChecked(object sender,RoutedEventArgs e){if(rendering)return;var check=(CheckBox)sender;var item=(Item)check.Tag;item.Done=check.IsChecked==true;item.CompletedAt=item.Done?DateTime.Now.ToString("s"):"";var text=(TextBlock)check.Content;text.TextDecorations=item.Done?TextDecorations.Strikethrough:null;Save();UpdateStats();}
  void AddTask(){string text=entry.Text.Trim();if(text.Length==0)return;Flush();state.Items.Add(new Item{Text=text,Kind=kind,Period=Logic.Key(kind,date)});entry.Clear();Save();Render();entry.Focus();}
  Item Selected(){var row=tasks.SelectedItem as ListBoxItem;return row==null?null:row.Tag as Item;}
  void Edit(){var i=Selected();if(i==null)return;Flush();string text=Ask("编辑任务",i.Text);if(String.IsNullOrWhiteSpace(text))return;i.Text=text.Trim();Save();Render();}
  void Delete(){var i=Selected();if(i==null)return;if(MessageBox.Show(this,"删除任务："+i.Text+"？","Personal Plan",MessageBoxButton.YesNo)!=MessageBoxResult.Yes)return;Flush();state.Items.Remove(i);Save();Render();}
  void Carry(){var i=Selected();if(i==null)return;Flush();DateTime next=kind=="month"?Logic.Start(kind,date).AddMonths(1):Logic.Start(kind,date).AddDays(kind=="week"?7:1);i.Period=Logic.Key(kind,next);i.Done=false;i.CompletedAt="";Save();Render();}
  void SetDate(DateTime d){Flush();date=d.Date;Render();}
  void Move(int n){SetDate(kind=="month"?date.AddMonths(n):date.AddDays(kind=="week"?7*n:n));}
  void ChooseDate(){string value=Ask("选择日期（yyyy-MM-dd）",Logic.Iso(date));if(value==null)return;DateTime d;if(DateTime.TryParseExact(value.Trim(),"yyyy-MM-dd",System.Globalization.CultureInfo.InvariantCulture,System.Globalization.DateTimeStyles.None,out d))SetDate(d);else MessageBox.Show(this,"请输入 yyyy-MM-dd 格式的日期。","Personal Plan");}
  Window Dialog(string title,double height){return new Window{Title=title,Icon=this.Icon,Width=420,Height=Math.Min(height,SystemParameters.WorkArea.Height-30),Owner=IsVisible?this:null,WindowStartupLocation=WindowStartupLocation.CenterScreen,Background=Brush(Light?"#F0F6FC":"#102033"),Foreground=Brush(state.Settings.TextColor),FontFamily=FontFamily,FontSize=12,Resources=Resources,Topmost=Topmost,ResizeMode=ResizeMode.NoResize};}
  string Ask(string title,string original){var w=Dialog(title,170);var p=new StackPanel{Margin=new Thickness(18)};w.Content=p;var box=new TextBox{Text=original};p.Children.Add(box);var save=Btn("保存",delegate{w.DialogResult=true;});save.Margin=new Thickness(0,16,0,0);p.Children.Add(save);w.Loaded+=delegate{box.Focus();box.SelectAll();};return w.ShowDialog()==true?box.Text:null;}
  void Export(){Flush();var dialog=new Forms.SaveFileDialog{Filter="文本文件|*.txt",FileName="Personal Plan-"+Logic.Key(kind,date)+".txt"};if(dialog.ShowDialog()!=Forms.DialogResult.OK)return;var n=Note(kind,date);var b=new StringBuilder(period.Text+"\r\n"+stats.Text+"\r\n");foreach(var i in Current())b.AppendLine((i.Done?"[完成] ":"[待办] ")+i.Text);b.AppendLine("\r\n复盘备注\r\n"+n.Text+"\r\nAI 总结\r\n"+n.AI);File.WriteAllText(dialog.FileName,b.ToString(),new UTF8Encoding(true));}
  void InitTray(){tray=new Forms.NotifyIcon{Text="Personal Plan",Icon=System.Drawing.Icon.ExtractAssociatedIcon(System.Reflection.Assembly.GetExecutingAssembly().Location),Visible=true};var menu=new Forms.ContextMenuStrip();menu.Items.Add("展开便签",null,delegate{Dispatcher.Invoke((Action)Expand);});menu.Items.Add("迷你浮窗",null,delegate{Dispatcher.Invoke((Action)MinimizeFloat);});menu.Items.Add("设置",null,delegate{Dispatcher.Invoke((Action)Settings);});menu.Items.Add("退出",null,delegate{Dispatcher.Invoke((Action)Quit);});tray.ContextMenuStrip=menu;tray.DoubleClick+=delegate{Expand();};tray.BalloonTipClicked+=delegate{Expand();};}
  public void Quit(){quitting=true;Flush();Close();Application.Current.Shutdown();}
  void Expand(){if(mini!=null)mini.Hide();Show();Activate();}
  void MinimizeFloat(){Flush();if(mini==null){mini=new Window{Title="Personal Plan · 迷你浮窗",Icon=this.Icon,Width=238,Height=76,WindowStyle=WindowStyle.None,AllowsTransparency=true,Background=Brushes.Transparent,Topmost=true,ResizeMode=ResizeMode.NoResize,Resources=Resources};var b=new Border{CornerRadius=new CornerRadius(18),Background=Brush("#3307121F"),BorderBrush=Brush("#554FA9BD"),BorderThickness=new Thickness(1),Padding=new Thickness(14,8,10,8)};mini.Content=b;var g=Columns(1,40);b.Child=g;var p=new StackPanel();p.Children.Add(Label("Personal Plan",15,"#D9F9FF"));miniText=Label("",11,"#D6EAF3");p.Children.Add(miniText);Place(g,p,0);miniRate=Label("0%",15,"#8FEAF3");miniRate.FontFamily=new FontFamily("Consolas");Place(g,miniRate,1);mini.MouseLeftButtonDown+=delegate(object s,MouseButtonEventArgs e){if(e.ClickCount==2)Expand();else{mini.DragMove();var area=SystemParameters.WorkArea;mini.Left=Math.Max(area.Left,Math.Min(area.Right-mini.Width,mini.Left));mini.Top=Math.Max(area.Top,Math.Min(area.Bottom-mini.Height,mini.Top));state.Settings.MiniX=(int)mini.Left;state.Settings.MiniY=(int)mini.Top;Save();}};var cm=new ContextMenu();cm.Items.Add(Menu("展开便签",Expand));cm.Items.Add(Menu("设置",Settings));cm.Items.Add(Menu("退出",Quit));b.ContextMenu=cm;var a=SystemParameters.WorkArea;mini.Left=state.Settings.MiniX<0?a.Right-mini.Width-24:Math.Max(a.Left,Math.Min(a.Right-mini.Width,state.Settings.MiniX));mini.Top=state.Settings.MiniY<0?a.Top+24:Math.Max(a.Top,Math.Min(a.Bottom-mini.Height,state.Settings.MiniY));}ApplyTheme();UpdateMini();Hide();mini.Show();}
  void UpdateMini(){if(mini==null)return;var a=state.Items.Where(x=>x.Kind=="day"&&x.Period==Logic.Key("day",DateTime.Today)).ToList();miniText.Text=DateTime.Today.ToString("MM.dd")+"  今日 "+a.Count(x=>x.Done)+" / "+a.Count;miniRate.Text=(a.Count==0?0:Math.Round(100.0*a.Count(x=>x.Done)/a.Count))+"%";}
  void SetAutoStart(){if(preview)return;using(var k=Registry.CurrentUser.CreateSubKey(@"Software\Microsoft\Windows\CurrentVersion\Run")){if(state.Settings.AutoStart)k.SetValue("PersonalPlan","\""+System.Reflection.Assembly.GetExecutingAssembly().Location+"\"");else k.DeleteValue("PersonalPlan",false);}}
  async Task Generate(string k,DateTime d,bool auto){if(busy)return;string secret="";try{secret=Storage.Decrypt(state.Settings.Secret);}catch{}if(String.IsNullOrWhiteSpace(secret)){if(!auto){MessageBox.Show(this,"请在设置中填写 DeepSeek API key。","Personal Plan");Settings();}return;}var n=Note(k,d);if(!String.IsNullOrEmpty(n.AI)){if(auto)return;if(MessageBox.Show(this,"替换当前 AI 总结？","Personal Plan",MessageBoxButton.YesNo)!=MessageBoxResult.Yes)return;}busy=true;aiButton.IsEnabled=false;status.Text="AI 正在生成总结…";try{string prompt=AI.Prompt(state,k,d);if(prompt.Length>100000)throw new Exception("本周期内容过多，请精简后重试。");n.AI=await AI.Generate(secret,state.Settings.Model,prompt);n.GeneratedAt=DateTime.Now.ToString("yyyy-MM-dd HH:mm");Save();if(k==kind&&Logic.Key(k,d)==Logic.Key(kind,date))summary.Text=n.AI+"\n\n生成于 "+n.GeneratedAt;}catch(Exception e){status.Text="AI 总结失败，可重试";if(!auto)MessageBox.Show(e.Message,"AI 总结失败");else Balloon("AI 总结未完成",e.Message);}finally{busy=false;aiButton.IsEnabled=true;}}
  void Balloon(string title,string text){if(tray==null)return;tray.BalloonTipTitle=title;tray.BalloonTipText=text;tray.ShowBalloonTip(8000);}
  async Task Remind(){DateTime now=DateTime.Now;var due=Logic.Due(now,state.Settings).Where(k=>!state.Reminded.Contains(Logic.Iso(now)+"/"+k)).ToList();if(due.Count==0)return;foreach(string k in due)state.Reminded.Add(Logic.Iso(now)+"/"+k);Save();Flush();ShowReminder(now,due);foreach(string k in due.Where(x=>x!="day"))if(state.Settings.AutoAI){while(busy&&!quitting)await Task.Delay(500);if(!quitting)await Generate(k,now,true);}}
  void ShowReminder(DateTime d,System.Collections.Generic.List<string> due){Balloon("17:30 · 复盘时间",String.Join(" / ",due.Select(k=>Logic.Name(k)+"总结与下期计划")));if(reminder!=null)reminder.Close();reminder=Dialog("Personal Plan · 复盘时间",160+due.Count*56);var p=new StackPanel{Margin=new Thickness(18)};reminder.Content=p;p.Children.Add(Label("总结今天，安排下一步",18,"#8FEAF3"));foreach(string k in due){string capture=k;var g=Columns(1,1);Place(g,Btn("查看"+Logic.Name(k)+"总结",delegate{Flush();kind=capture;date=d;Render();Expand();reminder.Close();}),0);Place(g,Btn("写下期"+Logic.Name(k)+"计划",delegate{Flush();kind=capture;date=capture=="month"?Logic.Start(capture,d).AddMonths(1):Logic.Start(capture,d).AddDays(capture=="week"?7:1);Render();Expand();reminder.Close();entry.Focus();}),1);p.Children.Add(g);}p.Children.Add(Btn("10 分钟后提醒",delegate{var snooze=new DispatcherTimer{Interval=TimeSpan.FromMinutes(10)};snooze.Tick+=delegate{snooze.Stop();ShowReminder(d,due);};snooze.Start();reminder.Close();}));reminder.Show();System.Media.SystemSounds.Asterisk.Play();}
