   p.Children.Add(Label("DeepSeek API key（本机加密保存）",12,"#C2DAE7"));var key=new PasswordBox{Margin=new Thickness(0,8,0,12),Padding=new Thickness(8),Background=Brush(Light?"#E4EDF5":"#102B40"),Foreground=Brush(state.Settings.TextColor)};try{key.Password=Storage.Decrypt(state.Settings.Secret);}catch{}p.Children.Add(key);p.Children.Add(Label("模型",12,"#C2DAE7"));var model=new TextBox{Text=state.Settings.Model,Margin=new Thickness(0,6,0,12)};p.Children.Add(model);p.Children.Add(Label("休息日期（yyyy-MM-dd，逗号分隔）",12,"#C2DAE7"));var off=new TextBox{Text=state.Settings.Holidays,Margin=new Thickness(0,6,0,12)};p.Children.Add(off);p.Children.Add(Label("调休上班日期（优先级最高）",12,"#C2DAE7"));var on=new TextBox{Text=state.Settings.Workdays,Margin=new Thickness(0,6,0,12)};p.Children.Add(on);var help=Label("工作日默认周一至周五。总结时会将对应周期任务与备注发送至 DeepSeek，并使用你的 API 余额。",11,"#9ABACD");help.TextWrapping=TextWrapping.Wrap;p.Children.Add(help);
